def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max(
        {v for row in grid for v in row},
        key=lambda v: sum(row.count(v) for row in grid)
    )

    # Label orthogonally connected foreground components.
    labels = [[-1] * w for _ in range(h)]
    component = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or labels[r][c] != -1:
                continue
            labels[r][c] = component
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] != background
                            and labels[ny][nx] == -1):
                        labels[ny][nx] = component
                        stack.append((ny, nx))
            component += 1

    out = [row[:] for row in grid]

    # Bridge gaps between distinct components on the same row or column.
    for r in range(h):
        cells = [c for c in range(w) if labels[r][c] != -1]
        for a, b in zip(cells, cells[1:]):
            if labels[r][a] != labels[r][b]:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    for c in range(w):
        cells = [r for r in range(h) if labels[r][c] != -1]
        for a, b in zip(cells, cells[1:]):
            if labels[a][c] != labels[b][c]:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    return out
