        if grid[r][c0] == bg:
            out[r][c0] = 2
        if grid[r][c1] == bg:
            out[r][c1] = 2

    # Restore interrupted straight runs supported by multiple markers.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != bg]
